import React, { useState } from 'react';
import styles from '../css/Weather.moudule.css'

const Weather = () => {
  const [city, setCity] = useState('');
  const [weatherData, setWeatherData] = useState(null);

  const API_KEY = '7ac5efbe309f3e7a20018760eb67b567';

  const fetchWeather = async () => {
    if (!city) {
      alert('Please enter a city name.');
      return;
    }

    try {
      const response = await fetch(
          `https://api.openweathermap.org/data/2.5/weather?q=${city}&appid=${API_KEY}&units=metric`
      );
      const data = await response.json();
      console.log(data); // 데이터를 콘솔에 출력
      if (data.cod === 200) {
        setWeatherData(data);
      } else {
        alert('City not found!');
        setWeatherData(null);
      }
    } catch (error) {
      console.error('Error fetching weather data:', error);
    }
  };

  return ( // 반드시 return 추가
    <div className={styles.container}>
      <h2>Weather Information</h2>
      <input
        className={styles.input}
        type="text"
        placeholder="Enter city"
        value={city}
        onChange={(e) => setCity(e.target.value)}
      />
      <button className={styles.button} onClick={fetchWeather}>Get Weather</button>
      {weatherData && (
        <div className={styles['weather-info']}>
          <p>Temperature: {weatherData.main.temp}°C</p>
          <p>Weather: {weatherData.weather[0].description}</p>
        </div>
      )}
    </div>
  );
};


export default Weather; // 반드시 추가
